{
    AxSalesTable        locAxSalesTable = next syncSalesTable(_purchTable,_salesTable,_forceAddressSync);
  /*  locAxSalesTable.parmAvaKCS_FreightCostStatus(_salesTable.KCS_FreightCostStatus);
